// One sample enquiry, shaped exactly like a form/webhook payload.
// In production this node is replaced by your trigger (form, webhook, email).
return [{
  json: {
    name: 'Ayesha Khan',
    channel: 'website form',
    message: 'I have tooth pain and need an emergency appointment this week.'
  }
}];

// SIMULATED LLM STEP.
// This Code node stands in for a real LLM classification node so the
// lesson runs with no API key. It returns the same three labels a real
// model would be prompted to return: booking, pricing, research.
// To use a real model, replace this node with an LLM node (for example
// the OpenAI or Basic LLM Chain node) using the prompt in the lesson
// README, keeping the output labels identical.
const text = $input.first().json.message.toLowerCase();
let category = 'research';
if (/(book|appointment|emergency|pain)/.test(text)) {
  category = 'booking';
} else if (/(cost|price|much)/.test(text)) {
  category = 'pricing';
}
return [{ json: { ...$input.first().json, category } }];

const first = $input.first().json.name.split(' ')[0];
const category = $input.first().json.category;
const reply = category === 'pricing'
  ? `Hi ${first}, teeth whitening is GBP 299 for a 60 minute session. Happy to book you a free consult first if you like.`
  : `Hi ${first}, thanks for looking us up. Shout if you would like a price list or a tour of the clinic, no pressure.`;
return [{ json: { ...$input.first().json, reply } }];
